import{_ as t,c as a,o,a3 as s}from"./chunks/framework.Dokpd4od.js";const m=JSON.parse('{"title":"Time off","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/time-off/index.md","filePath":"master/human-resources/time-off/index.md","lastUpdated":1791902625000}'),r={name:"master/human-resources/time-off/index.md"};function n(l,e,i,d,h,p){return o(),a("div",null,e[0]||(e[0]=[s(`<h1 id="time-off" tabindex="-1">Time off <a class="header-anchor" href="#time-off" aria-label="Permalink to &quot;Time off&quot;">​</a></h1><p>Time Off lets your people ask for leave and lets managers approve it. It keeps a balance of days for each person and shows every request on a calendar. You define the kinds of leave, such as <strong>Paid Time Off</strong> or <strong>Sick Time Off</strong>, and decide which ones need days given up front.</p><blockquote><p><strong>In simple words:</strong> Time Off is where staff ask for days away from work and managers say yes or no.</p></blockquote><p>Open the <strong>Time Off</strong> app from the main menu. The top bar shows five menus.</p><h2 id="how-time-off-flows" tabindex="-1">How time off flows <a class="header-anchor" href="#how-time-off-flows" aria-label="Permalink to &quot;How time off flows&quot;">​</a></h2><p>Every request follows the same path. Some steps happen only once, when you set up.</p><ol><li><strong>Set up leave types and holidays.</strong> Create the kinds of leave and list your public holidays.</li><li><strong>Allocate days.</strong> Give each person a number of days, but only for leave types that need it.</li><li><strong>Request time off.</strong> The employee picks a type and dates.</li><li><strong>Approve or refuse.</strong> A manager reviews the request.</li><li><strong>Balance and calendar update.</strong> The days leave the balance and the request appears on the calendar.</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Leave types and holidays  &gt;  Allocation (if needed)  &gt;  Request</span></span>
<span class="line"><span>        &gt;  Approve or Refuse  &gt;  Balance and calendar</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">Allocation first</p><p>A leave type set to <strong>Requires Allocation: Yes</strong> needs days before anyone can ask for it. A type set to <strong>No Limit</strong> has no balance to run out of.</p></div><h2 id="the-five-menus" tabindex="-1">The five menus <a class="header-anchor" href="#the-five-menus" aria-label="Permalink to &quot;The five menus&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu</th><th>What it holds</th><th>Sidebar labels</th></tr></thead><tbody><tr><td><strong>My Time</strong></td><td>Your balance cards, your calendar, the Holidays window and your own lists</td><td><strong>Dashboard</strong>, <strong>My Time off</strong>, <strong>My Allocation</strong></td></tr><tr><td><strong>Overview</strong></td><td>A full year calendar with requests of all employees</td><td>None</td></tr><tr><td><strong>Management</strong></td><td>The lists where managers approve and refuse requests and allocations</td><td><strong>Time off</strong>, <strong>Allocation</strong></td></tr><tr><td><strong>Reporting</strong></td><td>A list of requests grouped by employee</td><td><strong>By Employees</strong></td></tr><tr><td><strong>Configuration</strong></td><td>Leave types, public holidays and mandatory days</td><td><strong>Leave Types</strong>, <strong>Public Holidays</strong>, <strong>Mandatory Holidays</strong></td></tr></tbody></table><p>The <strong>Configuration</strong> sidebar also holds other entries. This guide covers the three above. The page title for <strong>Mandatory Holidays</strong> is <strong>Mandatory Days</strong>.</p><h2 id="leave-types-that-come-with-the-app" tabindex="-1">Leave types that come with the app <a class="header-anchor" href="#leave-types-that-come-with-the-app" aria-label="Permalink to &quot;Leave types that come with the app&quot;">​</a></h2><p>Seven leave types are ready to use.</p><ul><li><strong>Paid Time Off:</strong> needs an allocation.</li><li><strong>Sick Time Off:</strong> no limit.</li><li><strong>Compensatory Days:</strong> no limit.</li><li><strong>Unpaid:</strong> no limit.</li><li><strong>Parental Leaves:</strong> needs an allocation. Employees can ask for extra days.</li><li><strong>Training Time Off:</strong> needs an allocation.</li><li><strong>Extra Hours:</strong> no limit.</li></ul><p>Sample data also gives ten employees 20 days of <strong>Paid Time Off</strong> for 2026. See <a href="./setup/time-off-types.html">Leave types</a> for every setting.</p><h2 id="relation-to-employees" tabindex="-1">Relation to Employees <a class="header-anchor" href="#relation-to-employees" aria-label="Permalink to &quot;Relation to Employees&quot;">​</a></h2><p>Time Off works on employees. A person needs an employee record before they can request leave. The <strong>Time Off</strong> approver field on the employee form, under <strong>Work Information</strong>, names the user who approves their leave. See <a href="./../employees/employees/add-employee.html">Add an employee</a>.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>New to Time Off? Follow <a href="./get-started/first-steps.html">First steps</a>.</li><li>Learn the settings in <a href="./setup/">Setup</a>.</li><li>Learn requests in <a href="./requests/">Requests</a>.</li><li>Learn allocations in <a href="./allocations/">Allocations</a>.</li><li>See the grouped list in <a href="./reporting/by-employees.html">By Employees</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./requests/">Time off requests</a></li><li><a href="./allocations/">Allocations</a></li><li><a href="./../employees/">Employees overview</a></li></ul>`,22)]))}const g=t(r,[["render",n]]);export{m as __pageData,g as default};
